public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int n = sc.nextInt();
    int[] positions = new int[n + 1];
    Arrays.fill(positions, -1);
    int count = 0;

    for (int i = 0; i < 2 * n; i++) {
        int color = sc.nextInt();
        if (positions[color] == -1) {
            positions[color] = i;
        } else {
            if (i - positions[color] == 2) {
                count++;
            }
            positions[color] = i;
        }
    }
    System.out.print(count);
}
